//! 🔐️ Shared receiving keeps its source, output and callback frame in one movable owner.
use semio_framework_value_native_decoding::{NativeDecodeControl,NativeSharedAdmission,OriginalReceivingPrimary};
use semio_framework_value_control_contract::{RetainedCloneGrant,RetainedCloneProgress,RetainedCloneStep,RetainedWorkOutcome,RetirementDemand,ValueError,retained_clone_grant_admits};
use semio_framework_value_retained_clone::retained_clone::RetainedCloneClose;
use semio_framework_value_retirement::retirement::RetireOwned;
use semio_framework_value_shared_issuance::{SealedShared,SharedIssuer};
use std::mem::{ManuallyDrop,size_of};

/// 🧳️ One movable owner carries the actual input, output and original pending admission together.
pub struct NativeSharedSlots<T:RetireOwned+Send+Sync+'static,R:RetireOwned+Send+Sync+'static>{input:ManuallyDrop<Option<T>>,output:ManuallyDrop<Option<R>>,admission:NativeSharedAdmission<T>,retirement:RetainedCloneClose}
impl<T:RetireOwned+Send+Sync+'static,R:RetireOwned+Send+Sync+'static> Default for NativeSharedSlots<T,R>{fn default()->Self{Self{input:ManuallyDrop::new(None),output:ManuallyDrop::new(None),admission:Default::default(),retirement:Default::default()}}}
impl<T:RetireOwned+Send+Sync+'static,R:RetireOwned+Send+Sync+'static> NativeSharedSlots<T,R>{
 /// 📏️ Quotes the funded transfer of the original input into this owner.
 pub fn capture_demand()->RetirementDemand{RetirementDemand{copy_bytes:2*size_of::<Option<T>>(),depth:1,..Default::default()}}
 /// ⏱️ Quotes the actual original input-slot transfer.
 pub fn capture_work_demand(&self,source:&Option<T>)->Result<u64,ValueError>{if self.input.is_some()||self.output.is_some()||!self.admission.terminal_is_empty()||!self.retirement.is_empty()||source.is_none(){return Err(ValueError::invariant("shared slots require their empty original capture"))}Ok(1)}
 /// 📥️ Captures the input before any shared birth can be quoted.
 pub fn capture(&mut self,source:&mut Option<T>,effect:&mut crate::RetainedAllocationEffect<'_>)->RetainedWorkOutcome{let grant=effect.grant();let demand=Self::capture_demand();if self.input.is_some()||self.output.is_some()||!self.admission.terminal_is_empty()||!self.retirement.is_empty()||source.is_none(){return RetainedWorkOutcome{result:Err(ValueError::invariant("shared slots require their empty original capture").into()),work:0}}if !retained_clone_grant_admits(grant,demand)||effect.maximum_work_units()==0{return RetainedWorkOutcome{result:Ok(RetainedCloneStep::Progress(Default::default())),work:0}}match effect.performed(1){Ok(true)=>{},Ok(false)=>return RetainedWorkOutcome{result:Err(ValueError::literal(crate::ValueRefusalKind::WorkLimit,"original shared-slot work exceeded its authority")),work:1},Err(error)=>return RetainedWorkOutcome{result:Err(error),work:1}}*self.input=source.take();RetainedWorkOutcome{result:Ok(RetainedCloneStep::Complete(RetainedCloneProgress{copied_items:1,copied_bytes:demand.copy_bytes,..Default::default()})),work:1}}
 /// 📤️ Quotes publication of the retained result to its caller.
 pub fn take_demand()->RetirementDemand{RetirementDemand{copy_bytes:2*size_of::<Option<R>>(),depth:1,..Default::default()}}
 /// ⏱️ Quotes the actual original output-slot transfer.
 pub fn take_work_demand(&self,target:&Option<R>)->Result<u64,ValueError>{if target.is_some()||self.output.is_none()||!self.admission.terminal_is_empty(){return Err(ValueError::invariant("shared slots require their original completed output"))}Ok(1)}
 /// 🪣️ Transfers the completed output only on its own funded turn.
 pub fn take(&mut self,target:&mut Option<R>,effect:&mut crate::RetainedAllocationEffect<'_>)->RetainedWorkOutcome{let grant=effect.grant();let demand=Self::take_demand();if target.is_some()||self.output.is_none()||!self.admission.terminal_is_empty(){return RetainedWorkOutcome{result:Err(ValueError::invariant("shared slots require their original completed output").into()),work:0}}if !retained_clone_grant_admits(grant,demand)||effect.maximum_work_units()==0{return RetainedWorkOutcome{result:Ok(RetainedCloneStep::Progress(Default::default())),work:0}}match effect.performed(1){Ok(true)=>{},Ok(false)=>return RetainedWorkOutcome{result:Err(ValueError::literal(crate::ValueRefusalKind::WorkLimit,"original shared-slot work exceeded its authority")),work:1},Err(error)=>return RetainedWorkOutcome{result:Err(error),work:1}}*target=self.output.take();RetainedWorkOutcome{result:Ok(RetainedCloneStep::Complete(RetainedCloneProgress{copied_items:1,copied_bytes:demand.copy_bytes,..Default::default()})),work:1}}
 /// 👁️ Observes the original source without transferring its custody.
 pub fn input(&self)->Option<&T>{self.input.as_ref()}
 /// ⏪️ Returns captured input only when the original callback and birth are settled.
 pub fn reclaim_input(&mut self,target:&mut Option<T>,effect:&mut crate::RetainedAllocationEffect<'_>)->RetainedWorkOutcome{let grant=effect.grant();let d=Self::capture_demand();if target.is_some()||self.input.is_none()||!self.admission.terminal_is_empty(){return RetainedWorkOutcome{result:Err(ValueError::invariant("shared input requires its settled original admission").into()),work:0}}if !retained_clone_grant_admits(grant,d)||effect.maximum_work_units()==0{return RetainedWorkOutcome{result:Ok(RetainedCloneStep::Progress(Default::default())),work:0}}match effect.performed(1){Ok(true)=>{},Ok(false)=>return RetainedWorkOutcome{result:Err(ValueError::literal(crate::ValueRefusalKind::WorkLimit,"original shared-slot work exceeded its authority")),work:1},Err(error)=>return RetainedWorkOutcome{result:Err(error),work:1}}*target=self.input.take();RetainedWorkOutcome{result:Ok(RetainedCloneStep::Complete(RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,..Default::default()})),work:1}}
 /// 🪪️ Observes the retained original admission without transferring it.
 pub fn admission_ref(&self)->&NativeSharedAdmission<T>{&self.admission}
 /// 👁️ Observes whether the original output is ready for funded transfer.
 pub fn output_ready(&self)->bool{self.output.is_some()&&self.admission.terminal_is_empty()}
 /// 🪪️ Borrows the retained callback frame for original recovery.
 pub fn has_pending_recovery(&self)->bool{self.admission.has_pending_recovery()}
 pub fn resume_recovery(&mut self,control:&mut NativeDecodeControl<'_>)->RetainedWorkOutcome<RetainedCloneProgress,OriginalReceivingPrimary>{if self.has_pending_recovery(){self.admission.resume(control)}else{semio_framework_value_native_decoding::no_pending_receiving_recovery()}}
 pub fn admission(&mut self)->&mut NativeSharedAdmission<T>{&mut self.admission}
 /// 📏️ Quotes the next retained owned close turn.
 pub fn close_demand(&self,body:usize)->Result<RetirementDemand,ValueError>{if !self.admission.terminal_is_empty(){return self.admission.close_demand()}if !self.retirement.is_empty(){return self.retirement.next_owner_demands::<T>(false,&None,body)}if self.input.is_some(){return self.retirement.next_owner_demands::<T>(true,&None,body)}self.retirement.next_owner_demands::<R>(self.output.is_some(),&None,body)}
 /// ⛽️ Quotes the defining work of the next retained owned close turn.
 pub fn close_work_demand(&self,body:usize)->Result<u64,ValueError>{if !self.admission.terminal_is_empty(){self.admission.close_demand()?;return Ok(u64::from(self.admission.has_birth()))}if !self.retirement.is_empty(){return self.retirement.next_owner_work::<T>(false,&None,body)}if self.input.is_some(){return self.retirement.next_owner_work::<T>(true,&None,body)}self.retirement.next_owner_work::<R>(self.output.is_some(),&None,body)}
 /// ♻️ Retires the captured original values and any unpublished birth with funded work.
 pub fn close_step(&mut self,effect:&mut crate::RetainedAllocationEffect<'_>)->semio_framework_value_retirement::OriginalRetirementPoll{use crate::RetainedWorkPoll::Complete;let grant=effect.grant();if !self.admission.terminal_is_empty(){return self.admission.close_step(&mut effect.reborrow(grant,effect.maximum_work_units()).expect("retirement child exceeds original effect"))}if !self.retirement.is_empty(){return self.retirement.step_granted(effect)}if self.input.is_some(){let turn=self.retirement.begin_granted(&mut self.input,effect);return Complete(RetainedWorkOutcome{result:turn.result.map(|step|step.unwrap_or(RetainedCloneStep::Progress(Default::default()))).map_err(Into::into),work:turn.work})}if self.output.is_some(){let turn=self.retirement.begin_granted(&mut self.output,effect);return Complete(RetainedWorkOutcome{result:turn.result.map(|step|step.unwrap_or(RetainedCloneStep::Progress(Default::default()))).map_err(Into::into),work:turn.work})}Complete(RetainedWorkOutcome{result:Ok(RetainedCloneStep::Complete(Default::default())),work:0})}
 /// 🪹️ Observes whether every original slot and owned close is empty.
 pub fn requires_original_birth(&self)->bool{self.admission.terminal_is_empty()&&self.retirement.requires_original_birth()}
 pub fn close_original_birth_step(&mut self,original:&mut crate::OriginalRetirementCloseLoan<'_>,grant:RetainedCloneGrant)->semio_framework_value_retirement::OriginalRetirementPoll{self.retirement.step_original_birth(original,grant)}
 pub fn requires_original_control(&self)->bool{self.admission.terminal_is_empty()&&self.retirement.requires_original_control()}
 pub fn close_original_step(&mut self,original:&mut crate::OriginalRetirementCloseLoan<'_>,effect:&mut crate::RetainedAllocationEffect<'_>)->semio_framework_value_retirement::OriginalRetirementPoll{if self.requires_original_birth(){return crate::RetainedWorkPoll::Complete(RetainedWorkOutcome{result:Err(ValueError::literal(crate::ValueRefusalKind::UnsupportedOwner,"settle original birth first").into()),work:0})}if self.requires_original_control(){return self.retirement.step_original(original,effect)}self.close_step(effect)}
 pub fn terminal_is_empty(&self)->bool{self.input.is_none()&&self.output.is_none()&&self.admission.terminal_is_empty()&&self.retirement.is_empty()}
}
impl<T:RetireOwned+Send+Sync+'static> NativeSharedSlots<T,SealedShared<T>>{
 /// ⛽️ Quotes work only for the actual original sealed input and empty destination.
 pub fn advance_work_demand(&self)->Result<u64,ValueError>{if self.input.is_none()||self.output.is_some(){return Err(ValueError::invariant("sealed slots require original input and empty output"))}self.admission.shared_work_demand()}
 /// 🧷️ Advances the original sealed owner without lending its slots for replacement.
 pub fn advance(&mut self,control:&mut NativeDecodeControl<'_>,issuer:SharedIssuer<T>)->RetainedWorkOutcome<RetainedCloneProgress,OriginalReceivingPrimary>{control.receive_shared(&mut self.input,&mut self.output,issuer,&mut self.admission)}
 /// 📏️ Quotes the next physical sealed birth or publication.
 pub fn demand(&self)->RetirementDemand{self.admission.shared_demand()}
}
impl<T:RetireOwned+Send+Sync+'static> NativeSharedSlots<T,std::sync::Arc<T>>{
 /// ⛽️ Quotes work only for the actual original Arc input and empty destination.
 pub fn advance_work_demand(&self)->Result<u64,ValueError>{if self.input.is_none()||self.output.is_some(){return Err(ValueError::invariant("Arc slots require original input and empty output"))}self.admission.arc_work_demand()}
 /// 🖼️ Advances the original Arc owner without lending its slots for replacement.
 pub fn advance(&mut self,control:&mut NativeDecodeControl<'_>)->RetainedWorkOutcome<RetainedCloneProgress,OriginalReceivingPrimary>{control.receive_arc(&mut self.input,&mut self.output,&mut self.admission)}
 /// 📏️ Quotes the next physical Arc birth or publication.
 pub fn demand(&self)->RetirementDemand{self.admission.arc_demand()}
}
impl<T:RetireOwned+Send+Sync+'static,R:RetireOwned+Send+Sync+'static> Drop for NativeSharedSlots<T,R>{fn drop(&mut self){assert!(std::thread::panicking()||self.terminal_is_empty(),"shared slots require original funded closure")}}

#[cfg(test)]
mod tests{
 use super::*;use crate::native_decoding::{NativeConstructionRecipientIssuer,NativeDecodeConstructionRecipient,NativeDecodeWorkIssuer,NativeDecodeWorkRecipient};
 struct Construction;impl NativeDecodeConstructionRecipient for Construction{fn submitted(&self)->RetainedCloneProgress{Default::default()}fn grant(&mut self,d:RetirementDemand)->Result<RetainedCloneGrant,ValueError>{Ok(RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:d.copy_bytes,maximum_capacity_bytes:d.capacity_bytes,maximum_release_bytes:d.release_bytes,maximum_depth:d.depth})}fn accept(&mut self,grant:RetainedCloneGrant,progress:RetainedCloneProgress)->Result<(),ValueError>{assert!(progress.fits(grant));Ok(())}}
 struct Work;impl NativeDecodeWorkRecipient for Work{fn available_work(&mut self,observed:u64)->Result<u64,ValueError>{u64::MAX.checked_sub(observed).ok_or_else(||ValueError::invariant("native observed work exceeds its actual finite scope"))}fn admits(&mut self,_:u64,_:u64)->Result<bool,ValueError>{Ok(true)}}
 fn close<T:RetireOwned>(value:T){let mut owner=crate::retirement::controlled::ControlledRetirement::new(value).unwrap_or_else(|_|panic!("original owner requires paid close"));for _ in 0..10000{if owner.terminal_is_empty(){return}let d=owner.next_demand(4096).unwrap();let g=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:4096.max(d.copy_bytes),maximum_capacity_bytes:d.capacity_bytes,maximum_release_bytes:d.release_bytes,maximum_depth:d.depth};{let mut actual=None;owner.step(&mut crate::RetainedAllocationEffect::new(g,u64::MAX,&mut actual))}.unwrap();}panic!("original owner did not close")}
 /// 🔐️ Relocation retains the captured original payload and rejects replacement.
 #[test]fn native_shared_slots_keep_original_across_relocation_and_reject_replacement(){let fixture:serde_json::Value=serde_json::from_str(include_str!("../../🏭️construction/🧪️tests/🧫️fixtures/effect-frame.json")).unwrap();let mut original=Some(fixture["slotCustody"][0]["owner"].as_str().unwrap().to_owned());let pointer=original.as_ref().unwrap().as_ptr();let mut replacement=Some(fixture["slotCustody"][1]["candidate"].as_str().unwrap().to_owned());let grant=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:4096,maximum_capacity_bytes:4096,maximum_release_bytes:4096,maximum_depth:8};let mut slots=NativeSharedSlots::<String,SealedShared<String>>::default();let mut capture_actual=None;let mut capture_effect=crate::RetainedAllocationEffect::new(grant,u64::MAX,&mut capture_actual);assert!(slots.capture(&mut original,&mut capture_effect).result.is_ok());let mut reject_actual=None;let mut reject_effect=crate::RetainedAllocationEffect::new(grant,u64::MAX,&mut reject_actual);assert!(slots.capture(&mut replacement,&mut reject_effect).result.is_err());assert!(replacement.is_some());let mut slots=Box::new(slots);assert_eq!(slots.input().unwrap().as_ptr(),pointer);let mut callback=|_|true;let mut control=NativeDecodeControl::new(4096,&mut callback);let mut recipient=Construction;let mut issuer=NativeConstructionRecipientIssuer::new();let mut work=Work;let mut work_issuer=NativeDecodeWorkIssuer::new();for _ in 0..2{let mut loan=issuer.loan(&mut recipient);let mut work_loan=work_issuer.loan(&mut work);let turn=control.with_work_recipient(&mut work_loan,|control|control.with_construction_recipient(&mut loan,|control|Ok::<_,ValueError>(slots.advance(control,SharedIssuer::owned())))).unwrap();assert!(turn.result.is_ok())}assert!(slots.output_ready());let mut output=None;let mut take_actual=None;let mut take_effect=crate::RetainedAllocationEffect::new(grant,u64::MAX,&mut take_actual);assert!(slots.take(&mut output,&mut take_effect).result.is_ok());assert!(slots.terminal_is_empty());assert_eq!(output.as_ref().unwrap().get().as_ptr(),pointer);close(output.take().unwrap());close(replacement.take().unwrap());}
}
